/** Mesma conversão do `toNormal` do estudo; null quando a cidade, o mês ou a hora não existem. */
export function normalDe(
  cidade: string,
  mes: number | string,
  periodo: "dia" | "noite",
): NormalDoLugar | null {
  const n = NORMAIS_DO_ESTUDO[cidade]?.[String(mes)]?.[periodo === "dia" ? "15" : "3"];
  if (!n) return null;
  const o: NormalDoLugar = {};
  for (const k of ["temperature", "humidity", "clouds", "windSpeed"] as const) {
    const par = n[k];
    if (par) o[k] = { mu: par[0], sd: par[1] };
  }
  return o;
}
